query:
query O67940DaliNeighborhood($ids: [String!]!) {
  entries(entry_ids: $ids) {
    rcsb_id

    struct {
      title
    }

    exptl {
      method
    }

    rcsb_entry_info {
      resolution_combined
    }

    rcsb_accession_info {
      deposit_date
      initial_release_date
    }

    polymer_entities {
      rcsb_id

      rcsb_polymer_entity {
        pdbx_description
      }

      entity_poly {
        rcsb_entity_polymer_type
        pdbx_seq_one_letter_code_can
        rcsb_sample_sequence_length
        rcsb_mutation_count
      }

      rcsb_polymer_entity_container_identifiers {
        entity_id
        auth_asym_ids
        asym_ids

        reference_sequence_identifiers {
          database_name
          database_accession
        }
      }

      rcsb_entity_source_organism {
        ncbi_taxonomy_id
        ncbi_scientific_name
      }
    }
  }
}
